// Client for the build-time parts catalog in public/data/parts/
// (generated by scripts/partsCatalog.mjs from the manufacturer extracts).
//
// The catalog is split per engine family. A picker loads the index once, then
// `universal.json` plus the one family file the build needs, so nobody
// downloads the whole ~6 MB catalog to pick a set of rods.
//
// Records are facts from manufacturer catalogs: brand, part number,
// dimensions, fitment and source. There are no prices. Fitment is a catalog
// claim, never an "approved" fit: the planner shows it as
// no known conflict / possible conflict / known conflict.

export type PartCategory =
  | "crank" | "rod" | "piston" | "pistonKit" | "rotatingAssembly" | "ring" | "bearing"
  | "cam" | "lobe" | "lifter" | "pushrod" | "spring" | "retainer" | "rocker"
  | "head" | "intake" | "carb" | "efi" | "header" | "gasket" | "headGasket"
  | "fastener" | "damper" | "oilPump" | "timingSet"
  | "injector" | "injectionPump" | "liftPump" | "turbo" | "intercooler" | "manifold" | "tuner" | "oilCooler";

/** oem_replacement | carb_eo:<number> | no_eo_race_only | unknown. Absent on internal parts. */
export type EmissionsStatus = string;

export type FlowPoint = { lift: number; int?: number; exh?: number };

export type CatalogPart = {
  /** `<brand-slug>:<part number>`; stable across rebuilds. */
  id: string;
  /** Brand */
  m: string;
  /** Part number as the manufacturer prints it */
  p: string;
  cat: PartCategory | string;
  name: string;
  fit: { ci?: number[]; cyl?: number; y0?: number; y1?: number; notes?: string };
  /** Per-category dimensional specs; see scripts/parts-catalog/CLOUD_TASKS.md for keys. */
  spec: Record<string, unknown> & { flow?: FlowPoint[] };
  src: { doc: string; ed: string; url: string };
  em?: EmissionsStatus;
};

export type FamilyEntry = {
  fam: string;
  slug: string;
  /** True when the planner can match this family to an engine. */
  known: boolean;
  n: number;
  cats: Record<string, number>;
  file: string;
};

export type CatalogIndex = {
  generated: string;
  records: number;
  /** Cam lobe profiles live in their own file; they are reference data, not pickable parts. */
  lobes: { n: number; file: string };
  brands: { m: string; n: number }[];
  categories: Record<string, number>;
  families: FamilyEntry[];
};

const base = () => import.meta.env.BASE_URL.replace(/\/$/, "");

let indexPromise: Promise<CatalogIndex> | null = null;
const familyCache = new Map<string, Promise<CatalogPart[]>>();

export function loadPartsIndex(): Promise<CatalogIndex> {
  indexPromise ??= fetch(`${base()}/data/parts/index.json`)
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`parts index ${r.status}`))))
    .catch((e) => { indexPromise = null; throw e; });
  return indexPromise;
}

/** Records for one family, by its display name or slug. Empty when the family has no file. */
export async function loadPartsForFamily(famOrSlug: string): Promise<CatalogPart[]> {
  const index = await loadPartsIndex();
  const entry = index.families.find((f) => f.fam === famOrSlug || f.slug === famOrSlug);
  if (!entry) return [];
  let p = familyCache.get(entry.slug);
  if (!p) {
    p = fetch(`${base()}/data/parts/${entry.file}`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`parts ${entry.file} ${r.status}`))))
      .then((d: { parts: CatalogPart[] }) => d.parts)
      .catch((e) => { familyCache.delete(entry.slug); throw e; });
    familyCache.set(entry.slug, p);
  }
  return p;
}

/**
 * Everything a build can choose from: the engine's family plus the universal
 * parts (length-selected pushrods, springs sold by dimension). Optionally
 * narrowed to one category.
 */
export async function loadPartsForBuild(fam: string, cat?: PartCategory | string): Promise<CatalogPart[]> {
  const [own, universal] = await Promise.all([loadPartsForFamily(fam), loadPartsForFamily("Universal")]);
  const all = own.concat(universal);
  return cat ? all.filter((r) => r.cat === cat) : all;
}

/** Street builds must not be steered to competition-only parts. */
export function isStreetLegalChoice(part: CatalogPart): boolean {
  return !part.em || part.em === "oem_replacement" || part.em.startsWith("carb_eo:");
}
